// Parser for a fund house's own "Account Statement" for one folio (e.g. Tata Mutual Fund, generated by CAMS).
// Unlike the consolidated CAS it also lists the folio's SIP registrations, which are used to add new instalments.
// Works on positioned text from pdf.js via toLines().
import { isoDate, toLines, transactionType } from "./parse";

const DMY_RE = /^(\d{2})\/(\d{2})\/(\d{4})$/;
const ISIN_RE = /ISIN\s*:\s*(INF[0-9A-Z]{8}\d)/i;
const NAV_RE = /NAV\s+as\s+on\s+(\d{2}\/\d{2}\/\d{4})\s*:\s*([\d,.]+)/i;
const BAL_RE = /Current\s+Unit\s+Balance\s*:\s*([\d,.]+)/i;
const MV_RE = /Market\s+Value\s+as\s+on\s+(\d{2}\/\d{2}\/\d{4})\s*:\s*([\d,.]+)/i;
const STAMP_RE = /Stamp\s+Duty/i;
const GROSS_RE = /Gross\s+Amount\s*:\s*Rs\.?\s*([\d,.]+)/i;
const TOPUP_MONTHS = { monthly: 1, quarterly: 3, "half yearly": 6, "half-yearly": 6, yearly: 12, annually: 12 };

const dmy = (s) => { const m = DMY_RE.exec((s || "").trim()); return m ? `${m[3]}-${m[2]}-${m[1]}` : null; };
const num = (s) => {
  if (s == null) return null;
  const t = String(s).trim();
  const v = parseFloat(t.replace(/[(),\s]/g, ""));
  return isNaN(v) ? null : /^\(.*\)$/.test(t) || t.startsWith("-") ? -Math.abs(v) : v;
};
const isNum = (s) => /^\(?-?[\d,]*\d(\.\d+)?\)?$/.test((s || "").trim());
// Scheme names in the transaction section start with a short code, e.g. "TINAZ TATA Nifty 50 Index Fund - Direct Plan".
const cleanName = (s) => s.replace(/\s*-?\s*ISIN\s*:.*$/i, "").replace(/^[A-Z0-9]{3,10}\s+(?=\S)/, "").replace(/[\s-]+$/, "").replace(/\s+/g, " ").trim();
export const nameKey = (s) => (s || "").toLowerCase().replace(/\b(direct|regular|plan|growth|option|fund|the|of|idcw)\b/g, " ").replace(/[^a-z0-9]+/g, " ").trim();

export const isAMCStatement = (text) => /Account\s+Statement/i.test(text) && /Transaction\s+Details/i.test(text) && !/Consolidated\s+Account/i.test(text);

export function parseAMCStatement(pages) {
  const lines = toLines(pages);
  const all = lines.map((l) => l.text).join("\n");
  if (!isAMCStatement(all)) throw new Error("This doesn't look like a fund house account statement.");

  const folioM = /Folio\s+Number\s*(?:\t|\s)*:\s*(?:\t)?\s*([\d]+(?:\s*\/\s*\d+)?)/i.exec(all);
  const holderM = /Unit\s+Holder\s*(?:\t|\s)*:\s*(?:\t)?\s*([^\t\n]+)/i.exec(all);
  const dateM = /Statement\s+Date\s*:\s*(\d{2}-[A-Za-z]{3}-\d{4})/i.exec(all);
  const periodM = /Transactions\s+From\s+(\d{2}-[A-Za-z]{3}-\d{4})\s+to\s+(\d{2}-[A-Za-z]{3}-\d{4})/i.exec(all);
  const statementDate = dateM ? isoDate(dateM[1]) : null;
  const period = periodM ? { from: isoDate(periodM[1]), to: isoDate(periodM[2]) } : statementDate ? { from: null, to: statementDate } : null;
  const folio = { folio: folioM ? folioM[1].replace(/\s+/g, " ") : "", amc: "", pan: "", holder: holderM ? holderM[1].trim() : "", schemes: [] };
  const warnings = [];

  // ---- account summary: cost per scheme (gross amount invested, as the fund house counts it)
  const summaryCost = {};
  {
    const a = lines.findIndex((l) => /^Account\s+Summary/i.test(l.text));
    for (let i = a + 1; a >= 0 && i < lines.length && !/^Total\b|Asset\s+Allocation/i.test(lines[i].text.replace(/^.*\t(?=Total)/, "Total")); i++) {
      const c = lines[i].cells.map((x) => x.str);
      if (c.length >= 6 && dmy(c[1]) === null && /\d{2}-[A-Za-z]{3}-\d{4}/.test(c[1])) summaryCost[nameKey(c[0])] = num(c[4]);
    }
  }

  // ---- SIP registrations. A scheme name wraps above and below its data row, e.g.
  //   "Tata Gold ETF Fund of Fund Direct Plan | Once A" / "SIP | 06 | 06-Jun-2024 | ..." / "Growth | Month"
  const sips = [];
  {
    const a = lines.findIndex((l) => /^Systematic\s+Registrations/i.test(l.text));
    const b = lines.findIndex((l, i) => i > a && /Transactions\s+From|Transaction\s+Details/i.test(l.text));
    if (a >= 0) {
      const block = lines.slice(a + 1, b > a ? b : a + 60).filter((l) => !/^(Transaction|Scheme\s+Name|Type)\b/i.test(l.text));
      const isData = (l) => l.cells.some((c) => /^(SIP|STP|SWP)$/i.test(c.str)) && l.cells.filter((c) => /^\d{2}-[A-Za-z]{3}-\d{4}$/.test(c.str)).length >= 2;
      const nameOf = (l) => l.cells.filter((c) => c.x < 170 && !/^(Once\s+A|Month|SIP|STP|SWP)$/i.test(c.str)).map((c) => c.str).join(" ");
      const rows = block.map((l) => ({ l, data: isData(l), name: nameOf(l) }));
      const parts = rows.map(() => []);
      rows.forEach((r, i) => {
        if (r.data) { parts[i].push(r.name); return; }
        if (!r.name) return;
        if (rows[i + 1] && rows[i + 1].data) parts[i + 1].unshift(r.name);      // name starts on the line above the data
        else if (rows[i - 1] && rows[i - 1].data) parts[i - 1].push(r.name);     // and continues on the line below
      });
      rows.forEach((r, i) => {
        if (!r.data) return;
        const c = r.l.cells.map((x) => x.str);
        const type = c.find((s) => /^(SIP|STP|SWP)$/i.test(s)).toUpperCase();
        const dates = c.filter((s) => /^\d{2}-[A-Za-z]{3}-\d{4}$/.test(s));
        const di = c.indexOf(dates[1]);
        const nums = c.slice(di + 1).filter(isNum).map(num);
        const freqText = c.slice(di + 1).find((s) => TOPUP_MONTHS[s.toLowerCase()] != null) || "";
        const day = +(c.find((s) => /^\d{1,2}$/.test(s)) || dates[0].slice(0, 2));
        const name = parts[i].join(" ").replace(/\s+/g, " ").trim();
        if (type !== "SIP") { warnings.push(`Skipped a ${type} registration for ${name}.`); return; }
        sips.push({
          scheme: name, day, from: isoDate(dates[0]), to: isoDate(dates[1]),
          amount: nums[0] || 0, topUp: nums[1] || 0, topUpEvery: TOPUP_MONTHS[freqText.toLowerCase()] || 0, monthly: true,
        });
      });
    }
  }

  // ---- transactions, scheme by scheme. A scheme's header repeats on each page it spans.
  const byIsin = {};
  let cur = null, last = null, pendingName = "", stop = false;
  for (let i = 0; i < lines.length && !stop; i++) {
    const L = lines[i], t = L.text;
    if (/^Non\s+Financial\s+Transaction/i.test(t)) { stop = true; break; }
    const im = ISIN_RE.exec(t);
    if (im) {
      const isin = im[1].toUpperCase();
      const raw = (pendingName + " " + t.split("\t")[0]).trim();
      const navM = NAV_RE.exec(t) || NAV_RE.exec((lines[i - 1] || {}).text || "");
      if (!byIsin[isin]) {
        byIsin[isin] = { scheme: cleanName(raw), isin, rta: "CAMS", open: 0, close: null, valuation: {}, transactions: [] };
        folio.schemes.push(byIsin[isin]);
      }
      if (cur !== byIsin[isin]) last = null; // the same scheme continuing on a new page keeps its last row (a stamp-duty line may follow)
      cur = byIsin[isin]; pendingName = "";
      if (navM) cur.valuation = { ...cur.valuation, date: dmy(navM[1]), nav: num(navM[2]) };
      continue;
    }
    // Header split over lines: "TIPHGZ Tata India Pharma ... Growth-" / "NAV as on ..." / "ISIN:INF..."
    if (/^[A-Z0-9]{3,10}\s+\S.*-$/.test(t) && !/\t/.test(t)) { pendingName = t; continue; }
    if (/^NAV\s+as\s+on/i.test(t)) continue;
    const bm = BAL_RE.exec(t);
    if (bm && cur) {
      cur.close = num(bm[1]);
      const mv = MV_RE.exec(t);
      if (mv) cur.valuation = { ...cur.valuation, value: num(mv[2]), date: cur.valuation.date || dmy(mv[1]) };
      cur.valuation.cost = summaryCost[nameKey(cur.scheme)] ?? null;
      cur = null; last = null;
      continue;
    }
    if (!cur) continue;
    const c = L.cells.map((x) => x.str);
    const date = dmy(c[0]);
    if (date) {
      const desc = c[1] || "";
      const nums = c.slice(2).filter(isNum);
      if (/CREDIT\s+NOT\s+RECEIVED|REJECT/i.test(desc) || nums.length < 5) {
        // A failed instalment: shown with an amount but no units. Not money invested.
        last = { skip: true, date };
        continue;
      }
      const [amount, , nav, units, balance] = nums.map(num);
      last = { date, description: desc, amount, units, nav, balance, type: transactionType(desc, units) };
      cur.transactions.push(last);
      continue;
    }
    if (!last || last.skip) continue;
    if (STAMP_RE.test(t)) {
      const amt = num(c[c.length - 1]);
      if (amt) cur.transactions.push({ date: last.date, description: "Stamp duty", amount: amt, units: null, nav: null, balance: null, type: "STAMP_DUTY_TAX" });
      const g = GROSS_RE.exec(t);
      if (g) last.gross = num(g[1]);
      continue;
    }
    if (/STT\s+Paid/i.test(t)) {
      const amt = num(c[c.length - 1]);
      if (amt) cur.transactions.push({ date: last.date, description: "STT", amount: Math.abs(amt), units: null, nav: null, balance: null, type: "STT_TAX" });
      continue;
    }
    // A wrapped description line (e.g. a payout reference)
    if (!/^(Page\s*:|Call\s*:|Account\s+Statement|Folio\s+Number|Unit\s+Holder|Amount|Value|in\s+INR|Date)\b/i.test(t) && !isNum(c[c.length - 1])) {
      last.description = `${last.description} ${t.replace(/\t/g, " ")}`.trim();
    }
  }

  // The fund house: from the statement's own text (e.g. "SMS: TMF", tatamutualfund.com), else the first scheme's brand.
  const first = (folio.schemes[0] || {}).scheme || "";
  folio.amc = /tata\s*mutual\s*fund|tatamutualfund|\bTMF\b/i.test(all) ? "Tata Mutual Fund" : `${first.split(/\s+/)[0] || ""} Mutual Fund`.trim();

  // Link each SIP to its scheme (by name, then ISIN).
  for (const s of sips) {
    const k = nameKey(s.scheme);
    const match = folio.schemes.find((x) => nameKey(x.scheme) === k)
      || folio.schemes.find((x) => nameKey(x.scheme).startsWith(k) || k.startsWith(nameKey(x.scheme)));
    s.isin = match ? match.isin : "";
    if (!match) warnings.push(`Couldn't match the SIP for ${s.scheme} to a fund in the statement.`);
  }

  return { kind: "amc", period, statementDate, folios: [folio], sips, warnings };
}
